package com.singtel.redemptionservice;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.util.*;public interface LedgerRepository extends JpaRepository<CampaignLedger,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select l from CampaignLedger l where l.promotionId=:id")Optional<CampaignLedger> lock(@Param("id")UUID id);}